import React from 'react';


function Header(){
    return(
        <div className="header">
            <header>
                    <center>
                         <h1><i class="fa fa-shopping-bag" aria-hidden="true"></i>Welcome to online Shopping</h1>
                        <h2> <p>Foot Wear</p> </h2>
